const coins = $input.all().map(i => i.json);
const timeNow = new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' });

function formatCoin(coin, trendEmoji, trendLabel) {
  const priceINR = `₹${coin.current_price.toLocaleString('en-IN')}`;
  const change = `${coin.price_change_percentage_24h > 0 ? '+' : ''}${coin.price_change_percentage_24h.toFixed(2)}%`;
  const marketCap = `₹${coin.market_cap.toLocaleString('en-IN')}`;
  const volume = `₹${coin.total_volume.toLocaleString('en-IN')}`;
  const volumeTrend = coin.total_volume > coin.market_cap * 0.05 ? '🔺' : '🔻';
  const rank = `#${coin.market_cap_rank}`;
  const chartLink = `https://www.coingecko.com/en/coins/${coin.id}`;

  // ATH Insight
  const athDistance = ((coin.ath - coin.current_price) / coin.ath) * 100;
  const athLabel = athDistance < 10 ? '🟢 Near ATH' :
                   athDistance < 25 ? '🟡 Watch Zone' :
                   '🔴 Far Below ATH';

  // 24h Range Insight
  const high = coin.high_24h;
  const low = coin.low_24h;
  let rangePos = ((coin.current_price - low) / (high - low)) * 100;
  rangePos = Math.min(Math.max(rangePos, 0), 100);
  const rangeLabel = rangePos >= 80 ? '🔼 Near 24h High' :
                     rangePos <= 20 ? '🔽 Near 24h Low' :
                     '⚖️ In the Middle';
  const rangeStr = `${rangeLabel} (${rangePos.toFixed(1)}%)`;

  // Volatility Score
  const volatility = ((high - low) / coin.current_price) * 100;
  const volatilityBadge = volatility > 10 ? '🔥 High Volatility' :
                          volatility > 5 ? '🟦 Medium Volatility' :
                                           '🟩 Low Volatility';

  return {
    json: {
      message: `${trendEmoji} <b>Crypto Alert</b>: ${coin.name} (${coin.symbol?.toUpperCase()})
<b>Trend</b>: ${trendLabel}
<b>24h Change</b>: ${change}
<b>Current Price</b>: ${priceINR}
<b>Market Cap</b>: ${marketCap}
<b>24h Volume</b>: ${volume} ${volumeTrend}
<b>Global Rank</b>: ${rank}

<b>ATH Insight</b>: ${athLabel}
<b>24h Range</b>: ${rangeStr}
<b>Volatility</b>: ${volatilityBadge}

📊 <a href="${chartLink}">View Chart</a>

📅 Updated: ${timeNow}
📈 Data Source: CoinGecko (INR)
🔁 Triggered by: n8n 2025+ Automation`
    }
  };
}

// Split categories and format
const bullish = coins
  .filter(c => c.price_change_percentage_24h >= 5)
  .sort((a, b) => Math.abs(b.price_change_percentage_24h) - Math.abs(a.price_change_percentage_24h))
  .slice(0, 5)
  .map(c => formatCoin(c, '🚀', 'Bullish 🔥'));

const bearish = coins
  .filter(c => c.price_change_percentage_24h <= -5)
  .sort((a, b) => Math.abs(b.price_change_percentage_24h) - Math.abs(a.price_change_percentage_24h))
  .slice(0, 5)
  .map(c => formatCoin(c, '📉', 'Bearish ❄️'));

const sideways = coins
  .filter(c => Math.abs(c.price_change_percentage_24h) < 5)
  .sort((a, b) => Math.abs(b.price_change_percentage_24h) - Math.abs(a.price_change_percentage_24h))
  .slice(0, 5)
  .map(c => formatCoin(c, '⚖️', 'Sideways ⚖️'));

return [...bullish, ...bearish, ...sideways];

return $input.all().map(item => {
  const msg = item.json.message;

  const getValue = (label) => {
    const regex = new RegExp(`<b>${label}</b>:\\s*(.*?)\\n`);
    const match = msg.match(regex);
    return match ? match[1].trim() : '';
  };

  const coinMatch = msg.match(/<\/b>:\s*(.*?)\s\((.*?)\)/);
  const trendEmojiMatch = msg.match(/^(\S+)/); // Extracts the emoji at the very start
  const trendEmoji = trendEmojiMatch ? trendEmojiMatch[1] : '';

  return {
    json: {
      trend_emoji: trendEmoji,
      name: coinMatch ? coinMatch[1] : '',
      symbol: coinMatch ? coinMatch[2] : '',
      trend: getValue("Trend"),
      price_change_24h: getValue("24h Change"),
      current_price: getValue("Current Price"),
      market_cap: getValue("Market Cap"),
      volume_24h: getValue("24h Volume"),
      global_rank: getValue("Global Rank").replace('#', ''),
      ath_label: getValue("ATH Insight"),
      range_label: getValue("24h Range"),
      volatility: getValue("Volatility"),
      chart_link: (msg.match(/<a href="(.*?)">/) || [])[1] || '',
      updated_at: (msg.match(/📅 Updated: (.*?)\n/) || [])[1] || '',
    }
  };
});
